function getCategoryMeta(cat?: string) {
  const key = (cat || 'utilities').toLowerCase()
  return CATEGORY_META[key] || { label: cat || 'Source', color: '#D4D4D8', bg: 'rgba(255,255,255,0.06)', border: 'rgba(255,255,255,0.18)' }
}

